/**
 * "Why wasn't I picked?" — a plain-language, encouraging explanation for a
 * rejected application, plus what to do next.
 *
 * Grounded only in facts we hold (never guesses about the employer's mind):
 *   - skills the job asked for that the worker's profile lacks
 *   - how many people applied, and whether the job was filled
 *   - pay vs the worker's own rate expectations are NOT inferred
 *   - the recommended course from the skill-gap engine
 *   - 3 similar open jobs nearby the worker hasn't applied to yet
 *
 * The paragraph is generated by lib/llm (fallback: a template built from
 * the same facts) in the worker's language, and cached on the application.
 */

import { Types } from 'mongoose';
import { errors } from '@/lib/errors';
import { generateText } from '@/lib/llm';
import { ApplicationModel } from '@/modules/applications/application.model';
import { JobModel, type PublicJob } from '@/modules/jobs/job.model';
import { UserModel } from '@/modules/users/user.model';
import { computeForApplication, type SkillGapResult } from '@/modules/applications/skillGap.service';
import { RejectionExplainerModel } from './rejectionExplainer.model';

export interface RejectionExplainer {
  applicationId: string;
  jobTitle: string;
  explanation: string;
  facts: {
    missingSkills: string[];
    applicantsCount: number;
    jobFilled: boolean;
    profileCompletionHints: string[];
  };
  nextSteps: Array<{ kind: 'course' | 'profile' | 'job'; label: string; courseId?: string; jobId?: string }>;
  similarJobs: PublicJob[];
  source: 'ai' | 'fallback';
  generatedAt: string;
}

const LANG_NAME: Record<string, string> = { en: 'English', hi: 'Hindi', ta: 'Tamil', te: 'Telugu', kn: 'Kannada' };

function prettify(s: string): string {
  return s.replace(/[_-]+/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

function templateExplanation(f: {
  jobTitle: string; missing: string[]; applicants: number; filled: boolean; course: SkillGapResult['recommendedCourse'];
}): string {
  const parts: string[] = [];
  parts.push(`The employer chose someone else for "${f.jobTitle}". This doesn't mean you can't do the work.`);
  if (f.applicants > 5) parts.push(`${f.applicants} people applied, so competition was high.`);
  if (f.missing.length > 0) {
    parts.push(`The job asked for ${f.missing.slice(0, 3).map(prettify).join(', ')}, which isn't on your profile yet.`);
  } else {
    parts.push('Your skills matched what the job asked for — often the deciding factors are timing, distance or a worker the employer already knew.');
  }
  if (f.course) parts.push(`"${f.course.title}" (${f.course.durationMinutes} min) can help you show that skill next time.`);
  parts.push('Apply early to the similar jobs below — the first few applicants get looked at most.');
  return parts.join(' ');
}

export async function getRejectionExplainer(seekerId: string, applicationId: string): Promise<RejectionExplainer> {
  if (!Types.ObjectId.isValid(applicationId)) throw errors.applicationNotFound();
  const app = await ApplicationModel.findOne({ _id: applicationId, seekerId: new Types.ObjectId(seekerId) });
  if (!app) throw errors.applicationNotFound();
  if (app.status !== 'rejected') throw errors.conflict('This application was not rejected.');

  const [job, seeker, gap] = await Promise.all([
    JobModel.findById(app.jobId),
    UserModel.findById(seekerId).select('skills locale location photoUrl bio workHistory isVerified').lean(),
    computeForApplication({ seekerId, applicationId }),
  ]);
  if (!job) throw errors.notFound('Job no longer exists.');
  const locale = ((seeker as { locale?: string } | null)?.locale ?? 'en').slice(0, 2);

  const s = seeker as unknown as {
    skills?: string[]; photoUrl?: string | null; bio?: string | null; workHistory?: unknown[]; isVerified?: boolean;
    location?: { city?: string | null } | null;
  } | null;
  const hints: string[] = [];
  if (!s?.photoUrl) hints.push('Add a clear profile photo');
  if (!s?.isVerified) hints.push('Verify your ID');
  if (!s?.workHistory || s.workHistory.length === 0) hints.push('Add past work experience');
  if (!s?.bio) hints.push('Write a one-line intro about your work');

  // Similar open jobs the worker hasn't applied to.
  const applied = await ApplicationModel.find({ seekerId: new Types.ObjectId(seekerId) }).select('jobId').lean();
  const appliedIds = applied.map((a) => a.jobId);
  const mySkills = (s?.skills ?? []).map((x) => x.toLowerCase());
  const similarQuery: Record<string, unknown> = {
    status: 'active',
    _id: { $nin: [job._id, ...appliedIds] },
    crewHeadStartUntil: { $not: { $gt: new Date() } },
    $or: [{ type: job.type }, ...(mySkills.length ? [{ skills: { $in: mySkills } }] : [])],
  };
  const city = s?.location?.city ?? job.location?.city;
  if (city) similarQuery['location.city'] = city;
  const similar = await JobModel.find(similarQuery).sort({ createdAt: -1 }).limit(3);
  const similarJobs = similar.map((j) => j.toPublicJSON());

  const cached = await RejectionExplainerModel.findOne({ applicationId: app._id, locale }).lean();
  let explanation: string;
  let source: 'ai' | 'fallback';
  let generatedAt: Date;
  const facts = {
    missingSkills: gap.missingSkills,
    applicantsCount: job.applicantsCount ?? 0,
    jobFilled: job.status === 'filled',
    profileCompletionHints: hints,
  };
  if (cached) {
    explanation = cached.text;
    source = cached.source;
    generatedAt = cached.createdAt;
  } else {
    const fallback = templateExplanation({
      jobTitle: job.title, missing: gap.missingSkills, applicants: facts.applicantsCount,
      filled: facts.jobFilled, course: gap.recommendedCourse,
    });
    const r = await generateText({
      system:
        `You help blue-collar and gig workers in India understand a job rejection. Write ONE short paragraph (max 90 words) in ${LANG_NAME[locale] ?? 'English'}, ` +
        'warm, simple words, second person. Use ONLY the facts given — never invent reasons, never blame the worker, never speculate about the employer. ' +
        'End with one concrete next step. No lists, no headings.',
      prompt: JSON.stringify({
        jobTitle: job.title,
        jobSkills: job.skills ?? [],
        missingSkillsOnProfile: gap.missingSkills.map(prettify),
        applicants: facts.applicantsCount,
        jobFilled: facts.jobFilled,
        recommendedCourse: gap.recommendedCourse ? { title: gap.recommendedCourse.title, minutes: gap.recommendedCourse.durationMinutes } : null,
        profileGaps: hints,
        similarOpenJobsNearby: similarJobs.length,
      }),
      maxTokens: 300,
      fallback,
    });
    explanation = r.text;
    source = r.source;
    generatedAt = new Date();
    await RejectionExplainerModel.updateOne(
      { applicationId: app._id, locale },
      { $set: { text: explanation, source, createdAt: generatedAt } },
      { upsert: true },
    ).catch(() => undefined);
  }

  const nextSteps: RejectionExplainer['nextSteps'] = [];
  if (gap.recommendedCourse) {
    nextSteps.push({ kind: 'course', label: `Take "${gap.recommendedCourse.title}" (${gap.recommendedCourse.durationMinutes} min)`, courseId: gap.recommendedCourse.id });
  }
  for (const h of hints.slice(0, 2)) nextSteps.push({ kind: 'profile', label: h });
  for (const j of similarJobs) nextSteps.push({ kind: 'job', label: `Apply: ${j.title}`, jobId: j.id });

  return {
    applicationId: app.id,
    jobTitle: job.title,
    explanation,
    facts,
    nextSteps,
    similarJobs,
    source,
    generatedAt: generatedAt.toISOString(),
  };
}
